workspace "Bookshop" "A simple online bookshop" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who browses and buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop where customers can browse books and place orders" {
            webStore = container "Web Store" "The web application where customers browse books and place orders" "Web application"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Batch service"
        }

        customer -> bookshop.webStore "browses books and places orders via" "HTTPS"
        bookshop.webStore -> bookshop.orderProcessor "submits orders to" "Internal API"
    }

    views {
        systemContext bookshop "BookshopContext" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}

